// @ts-check
const { test, expect } = require('@playwright/test');
const fs = require('fs');
const path = require('path');

// Generated by the build script when webServer starts
const loadIcons = () =>
  JSON.parse(
    fs.readFileSync(path.join(__dirname, '..', 'dist', 'icons.json'), 'utf8'),
  );

test.describe('unknown paths', () => {
  // Browsers request /favicon.ico for every page. Forwarding it looped back to this Worker, failed with 500
  // after 5 seconds, and made the icon images loading in the meantime fail too
  for (const path of ['/favicon.ico', '/unknown']) {
    test(`${path} returns 404 right away`, async ({ request }) => {
      const res = await request.get(path, { timeout: 2000 });
      expect(res.status()).toBe(404);
    });
  }
});

test.describe('GET /api/svgs', () => {
  test('returns dist/icons.json as JSON', async ({ request }) => {
    const res = await request.get('/api/svgs');
    expect(res.status()).toBe(200);
    expect(res.headers()['content-type']).toBe(
      'application/json;charset=UTF-8',
    );
    expect(await res.json()).toEqual(loadIcons());
  });
});

test.describe('GET /api/icons', () => {
  test('returns the icon names with theme variants merged', async ({
    request,
  }) => {
    const res = await request.get('/api/icons');
    expect(res.status()).toBe(200);
    expect(res.headers()['content-type']).toBe(
      'application/json;charset=UTF-8',
    );

    const names = await res.json();
    const expected = [
      ...new Set(Object.keys(loadIcons()).map(i => i.split('-')[0])),
    ];
    expect(names).toEqual(expected);

    // themed icons appear once, without "-dark" / "-light"
    expect(names).toContain('java');
    expect(names).not.toContain('java-dark');
    expect(names.filter(n => n === 'java')).toHaveLength(1);
  });

  test('returns the same result with a trailing slash', async ({ request }) => {
    const a = await (await request.get('/api/icons')).json();
    const b = await (await request.get('/api/icons/')).json();
    expect(b).toEqual(a);
  });
});
